import test from 'node:test';
import assert from 'node:assert/strict';
import { allocateShares } from './split.mjs';

test('allocates each cent once and shares remainder fairly', () => {
  const shares = allocateShares(1000, 3);
  assert.deepEqual(shares, [334, 333, 333]);
  assert.equal(shares.reduce((sum, share) => sum + share, 0), 1000);
  assert.ok(shares.every(Number.isInteger));
});

test('handles totals smaller than the group', () => {
  assert.deepEqual(allocateShares(2, 4), [1, 1, 0, 0]);
});

test('rejects invalid totals and group sizes', () => {
  for (const total of [-1, 1.5, NaN]) assert.throws(() => allocateShares(total, 2));
  for (const people of [0, -1, 1.5, NaN]) assert.throws(() => allocateShares(100, people));
});
